def speak(text, lang, out_mp3, speed=145):
    wav = out_mp3 + ".raw.wav"
    voice = ("en-gb" if lang == "en" else lang) + "+f3"
    subprocess.run([ESPEAK, "-v", voice, "-s", str(speed), "-p", "52", "-g", "4", "-w", wav, text], check=True)
    # Warm it up: cut harsh highs, small room reverb, normalise loudness
    af = "highpass=f=90,lowpass=f=7000,equalizer=f=3000:t=q:w=1:g=-3,aecho=0.8:0.6:40:0.18,loudnorm=I=-16:TP=-1.5"
    subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", wav, "-af", af, "-ar", "44100", "-b:a", "96k", out_mp3], check=True)
    os.remove(wav)


for proj, texts in (("waterguard", WATER), ("aushadhbox", MEDI)):
    d = os.path.join(ROOT, proj, "assets", "audio", "voice")
    os.makedirs(d, exist_ok=True)
    for lang, text in texts.items():
        speak(text, lang, os.path.join(d, f"guide-{lang}.mp3"))
        print("voice", proj, lang)
    # English narration for the video (slightly slower)
    speak(texts["en"], "en", f"/tmp/{proj}_narration.mp3", speed=138)
